      id: "civ06",
      num: 6,
      titulo: "Prescrição e Decadência",
      conteudo: `Prescrição e decadência são institutos do Direito Civil que regulam a perda de direitos
ao longo do tempo, mas têm diferenças importantes.
A prescrição é a perda do direito de ação para exigir um direito violado após o decurso
de um prazo legal. O direito material continua existindo, mas não pode mais ser exigido judicial-
mente. Exemplo: Uma pessoa tem 5 anos para cobrar uma dívida decorrente de um contrato
particular (art. 206, § 5º, CC). Se não fizer isso dentro do prazo, ainda pode tentar receber ami-
gavelmente, mas não poderá exigir na Justiça.
Em virtude disso, percebe-se que a prescrição possui vinculação com o direito subjetivo,
ou seja, a pessoa atingida obrigará a outra a uma contraprestação.
Cabe destacar que na prescrição todos os prazos estão fixados junto aos artigos 205
(prazo de 10 anos) e 206 (cada parágrafo estabelece um prazo diferente, que varia de 01 a 05
anos). Há, ainda, causas que impedem e suspendem a prescrição. O art. 197 do CC/02 afirma
que não corre a prescrição nas seguintes hipóteses: a) entre os cônjuges, na constância da
sociedade conjugal; b) entre ascendente e descendente, durante o poder familiar; c) entre tute-
lados ou curatelados e seus tutores ou curadores, durante a tutela ou curatela. O art. 198 do
CC/02, por sua vez, preconiza que também não corre a prescrição contra os absolutamente in-
capazes (menores de 16 anos); contra os ausentes do País em serviço público da União, dos
Estados ou dos Municípios e contra os que se acharem servindo nas Forças Armadas, em tempo
de guerra.
Cuidar! A suspensão da prescrição ocorre quando o prazo de prescrição fica temporaria-
mente paralisado, mas não é perdido. Após cessar a causa da suspensão, o prazo continua de
onde parou. Em outras palavras, o prazo não começa do zero, mas sim de onde foi interrompido.
O impedimento, por outro lado, ocorre quando, por motivo legal, o prazo de prescrição não pode
correr, ou seja, a prescrição é bloqueada durante o período do impedimento. Ao contrário da
suspensão, o impedimento não faz o prazo "parar" temporariamente, mas sim impede que a
prescrição aconteça enquanto durar a causa que o impede (Tartuce, 2025).
Direito Civil`
